using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class ActionInstanceOutlineHandler : MonoBehaviour
{
	[Header("Shake")]
	[SerializeField]
	private float shakeAmount;

	[SerializeField]
	private float shakeDuration;

	[SerializeField]
	private Transform transformToShake;

	[Header("Components")]
	[SerializeField]
	protected ActionInstance actionInstance;

	[SerializeField]
	protected Material playerDiceOutline;

	[SerializeField]
	protected Material mustUseOutline;

	[SerializeField]
	protected Material highlightOutline;

	[Header("Brightness Animation")]
	[SerializeField]
	protected FloatReference brightnessOnDurationReference;

	[SerializeField]
	protected AnimationCurveReference brightnessOnCurveReference;

	[SerializeField]
	protected FloatReference brightnessStayBrightDurationReference;

	[SerializeField]
	protected FloatReference brightnessOffDurationReference;

	[SerializeField]
	protected AnimationCurveReference brightnessOffCurveReference;

	protected bool mustUse;

	protected Coroutine shakeCoroutine;

	private Vector3 originalLocalPosition;

	protected Material playerDiceOutlineRuntime;

	protected Material mustUseOutlineRuntime;

	protected Material highlightOutlineRuntime;

	protected ActionFace actionFace => actionInstance.ActionFace;

	public bool actionEnabled => actionInstance.ActionEnabled;

	protected DiceOwnerEnum diceOwnerEnum => actionInstance.DiceOwnerEnum;

	protected bool dragging => actionInstance.Dragging;

	public bool MustUse => mustUse;

	public virtual void UpdateOutlineAndMustUse()
	{
		if (actionFace.BattleAction.BaseBattleActionData.HasMandatoryBattleActionInteractionEnum())
		{
			mustUse = true;
		}
		else
		{
			mustUse = false;
		}
	}

	public void StopShakeCoroutine()
	{
		if (shakeCoroutine != null)
		{
			StopAllCoroutines();
			shakeCoroutine = null;
			transformToShake.localPosition = Vector3.zero;
		}
	}

	public void Shake()
	{
		if (!actionInstance.Discarding)
		{
			if (shakeCoroutine != null)
			{
				StopCoroutine(shakeCoroutine);
				transformToShake.localPosition = originalLocalPosition;
			}
			else
			{
				originalLocalPosition = transformToShake.localPosition;
			}
			shakeCoroutine = StartCoroutine(CoroutineUtility.ShakeRoutineEnumerator(transformToShake, shakeDuration, shakeAmount, delegate
			{
				shakeCoroutine = null;
			}));
		}
	}

	public void OnMouseOverEndTurnMustUse()
	{
		if (diceOwnerEnum != DiceOwnerEnum.ENEMY && mustUse && !dragging && actionEnabled)
		{
			PlayActionBrightnessAnimation();
		}
	}

	public void OnMouseOverEndTurn()
	{
		if (diceOwnerEnum != DiceOwnerEnum.ENEMY && actionEnabled && actionFace.BattleAction.GetDiceActionLogic(actionFace.ModifiedActionValue) != null && !dragging)
		{
			PlayActionBrightnessAnimation();
		}
	}

	public virtual void ToggleOutline(bool toggle, bool animation = true)
	{
	}

	protected virtual void PlayActionBrightnessAnimation()
	{
	}
}
